+      >
+        <thead style={{ background: "#f9fafb" }}>
+          <tr>
+            <th style={{ textAlign: "left", padding: "0.65rem", width: "15%" }}>
+              SKU
+            </th>
+            <th style={{ textAlign: "left", padding: "0.65rem" }}>Product</th>
+            <th style={{ textAlign: "right", padding: "0.65rem", width: "14%" }}>
+              Price
+            </th>
+            <th style={{ textAlign: "right", padding: "0.65rem", width: "14%" }}>
+              Inventory
+            </th>
+            <th style={{ textAlign: "left", padding: "0.65rem", width: "15%" }}>
+              Availability
+            </th>
+            <th style={{ textAlign: "left", padding: "0.65rem", width: "20%" }}>
+              Updated
+            </th>
+          </tr>
+        </thead>
+        <tbody>
+          {products.map((product) => (
+            <tr key={product.id} style={{ borderTop: "1px solid #e5e7eb" }}>
+              <td style={{ padding: "0.65rem", fontFamily: "ui-monospace, monospace" }}>
+                {product.id}
+              </td>
+              <td style={{ padding: "0.65rem" }}>{product.name}</td>
+              <td style={{ padding: "0.65rem", textAlign: "right" }}>
+                {currencyFormatter.format(product.priceCents / 100)}
+              </td>
+              <td style={{ padding: "0.65rem", textAlign: "right" }}>
+                {product.inventory}
+              </td>
+              <td style={{ padding: "0.65rem", textTransform: "capitalize" }}>
+                {formatAvailability(product.availability)}
+              </td>
+              <td style={{ padding: "0.65rem" }}>
+                {new Date(product.updatedAt).toLocaleString()}
+              </td>
+            </tr>
+          ))}
+        </tbody>
+      </table>
+    </main>
   );
 }
